on->occupiedCount >= $newSession->capacity ) { return false; } $this->regRepo->update( $registrationId, [ 'status' => 'transferred', 'active_slot' => null, 'transferred_at' => current_time( 'mysql', true ), ] ); $newRegId = $this->regRepo->insert( [ 'participation_id' => $oldReg->participationId, 'session_id' => $newSessionId, 'status' => 'confirmed', 'active_slot' => 1, 'created_at' => current_time( 'mysql', true ), ] ); $this->sessionRepo->update( $oldReg->sessionId, [ 'occupied_count' => max( 0, $oldSession->occupiedCount - 1 ), ] ); $this->sessionRepo->update( $newSessionId, [ 'occupied_count' => $newSession->occupiedCount + 1, ] ); return true; } public function confirmArrival( int $registrationId ): bool { return $this->regRepo->update( $registrationId, [ 'arrived_at' => current_time( 'mysql', true ), 'arrived_by_user_id' => get_current_user_id(), ] ); } }
